import{_ as t,o as a,c as s,a2 as r}from"./chunks/framework.BvlN9b-o.js";const u=JSON.parse('{"title":"Boundaries between Core and the reference example","description":"","frontmatter":{"docLocale":"en","counterpart":"/architecture/boundaries","contentType":"guide","prev":false,"next":false},"headers":[],"relativePath":"en/architecture/boundaries.md","filePath":"en/architecture/boundaries.md"}'),n={name:"en/architecture/boundaries.md"};function o(i,e,d,l,c,p){return a(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="boundaries-between-core-and-the-reference-example" tabindex="-1">Boundaries between Core and the reference example <a class="header-anchor" href="#boundaries-between-core-and-the-reference-example" aria-label="Permalink to &quot;Boundaries between Core and the reference example&quot;">​</a></h1><p>Core provides identity, sessions, membership, audit, idempotency, files, jobs, notifications, mail, API keys and general HTTP capabilities. The reference example plugs its own business in through the application entry; Core never depends back on it.</p><ul><li><strong>platform</strong> owns configuration, connection pools, migration running, the optional Redis text cache and logging initialization, and depends on neither the application nor the knowledge-base type.</li><li><strong>app</strong>&#39;s modules each own their use cases and tables; a pure <code>domain.rs</code> depends on neither HTTP nor the database.</li><li><strong>API entry</strong> assembles the Router/OpenAPI in <code>apps/api/src/lib.rs</code>; the generic builder accepts extra routes and contracts.</li><li><strong>contracts / sdk</strong> are generated from OpenAPI; the SDK&#39;s types use contracts.</li><li><strong>core</strong> holds platform-agnostic client helpers.</li><li><strong>ui / views</strong> provide generic React DOM components and shareable pages respectively.</li><li><strong>Web entry</strong> owns browser and Router wiring; shared views navigate through callbacks.</li></ul><p>The <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e2df5399c4b9da982ab8e043578a50a75c40f885/examples/knowledge-base/manifest.json" target="_blank" rel="noreferrer">example ownership manifest</a> records business directories, migrations, tests, tutorials and the explicit assembly blocks. Register new features there as you add them; the removal tooling later operates on exactly what is registered, and Core&#39;s capabilities are never deleted along with a reference example.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> boundaries:check</span></span></code></pre></div><p>The current check verifies package import directions, direct references from Core to reference types, infrastructure imports inside pure domains, the SQL tables each module declares ownership of, and the assembly manifest. Every Rust module&#39;s <code>module.json</code> is the entry point for table ownership; modules cooperate only through public interfaces — for example, Audit appends records inside the caller&#39;s transaction.</p><p>The SQL check works from strings in the source and the registered table names; it cannot prove everything about dynamic SQL, quoted identifiers or symbol aliases — those still need review. Rust visibility plus real HTTP/database tests complete the verification. Actual example-removal acceptance is exercised by the removal tooling&#39;s corresponding task.</p><p>When you bring your own business, use the public identity, files and jobs capabilities; never make Core depend on the example through private tables or reverse imports. For the decisions behind this, see <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e2df5399c4b9da982ab8e043578a50a75c40f885/docs/adr/0002-executable-removable-reference.md" target="_blank" rel="noreferrer">the executable-removable-reference ADR</a>.</p><p>Notifications owns job notification intents and the inbox; business code registers intents in the request transaction through public interfaces, and Jobs publishes notifications in the terminal-state transaction. Navigation targets are resolved by the app shell; Core views open them through callbacks; the target API always re-authorizes. Unknown targets never affect reading or marking as read.</p><p>API Keys manages generic credentials and their scopes. The application entry registers the scopes each module actually provides; business handlers obtain the current user through the public authentication capability, then perform their own resource authorization. Core&#39;s <code>profile:read</code> and key management survive example removal; one-time secrets never enter replays, queries or the mutation cache.</p><p>CoreOptions passes scope registration and the shared cache at the application assembly point. The cache only handles budgeted Redis I/O and in-process metering; Knowledge owns its own database authorization, body versions and keys; Core never stores or reuses business permission decisions.</p><p>RateLimit classifies requests in Core, maintains the bounded local fallback and the fixed policy metering; the Platform WindowCounter performs the limited Redis atomic operations. Cache and counters share a private transport implementation, each holding its own capacity and timeout budgets; business modules never send arbitrary Redis commands directly.</p><p>Identity owns reset validity, hashing, the short-lived cipher table and the mail handler; Mail provides bounded encryption/decryption and delivery capability, and Platform wraps SMTP. Jobs stores only the reset ID and owns leases and retries. Core&#39;s password-reset page, tutorial and browser tests are independent of knowledge-base ownership and survive example removal.</p><p>Platform Telemetry wraps the optional OTel exporter, W3C propagation, bounded metering and the lossy JSON log sink. Application uses tracing with public scopes; HTTP records the actor at authentication success points, Jobs saves observation metadata in the same transaction, the Worker starts a new attempt span from the persisted parent, and Audit records the currently valid trace ID. The domain never depends on OTel, and business payloads never carry runtime context.</p><p><code>just dev-observability</code> starts the generic Collector/Prometheus/Loki/Tempo/Grafana profile alongside the normal development entry; <code>just observability-down</code> stops only the observability services and keeps their volumes. Core&#39;s configuration reference, HTTP/job/storage metering, audit correlation, dashboards and protocol/failure tests all survive example removal. Trace IDs are never used for authorization, and sampling or telemetry-export failures never change business state. Raw request contents, credentials, signed URLs and third-party transport debug output never enter the observability pipeline.</p><hr><p>Source version：<code>e2df5399c4b9</code> · <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e2df5399c4b9da982ab8e043578a50a75c40f885/docs/architecture/module-boundaries.en.md" target="_blank" rel="noreferrer">Page Markdown</a></p>',17)])])}const b=t(n,[["render",o]]);export{u as __pageData,b as default};
